// Read a tuple of 2 item(s) with `readItem1`, `readItem2`, *etc.* on
// the correspondingly positioned item, or return an error.
//
// Each item is framed by [readElementDispatched], so an item reader accepts or
// rejects the positional element name (`v1`, `v2`, *etc.*) on its own for a scalar
// item, and discriminates on the class element name for an instance item.
func readTuple2[T1 any, T2 any](
	decoder *xml.Decoder,
	current xml.Token,
	readItem1 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T1, xml.Token, error),
	readItem2 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T2, xml.Token, error),
) (result aascommon.Tuple2[T1, T2], next xml.Token, err error) {
	var item1 T1
	item1, current, err = readElementDispatched(
		decoder, current, readItem1,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 0},
			)
		}
		return
	}

	var item2 T2
	item2, current, err = readElementDispatched(
		decoder, current, readItem2,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 1},
			)
		}
		return
	}

	result = aascommon.Tuple2[T1, T2]{
		Item1: item1,
		Item2: item2,
	}
	next = current
	return
}

// Read a tuple of 6 item(s) with `readItem1`, `readItem2`, *etc.* on
// the correspondingly positioned item, or return an error.
//
// Each item is framed by [readElementDispatched], so an item reader accepts or
// rejects the positional element name (`v1`, `v2`, *etc.*) on its own for a scalar
// item, and discriminates on the class element name for an instance item.
func readTuple6[T1 any, T2 any, T3 any, T4 any, T5 any, T6 any](
	decoder *xml.Decoder,
	current xml.Token,
	readItem1 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T1, xml.Token, error),
	readItem2 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T2, xml.Token, error),
	readItem3 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T3, xml.Token, error),
	readItem4 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T4, xml.Token, error),
	readItem5 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T5, xml.Token, error),
	readItem6 func(
		aDecoder *xml.Decoder,
		aCurrent xml.Token,
		aLocal string,
	) (T6, xml.Token, error),
) (result aascommon.Tuple6[T1, T2, T3, T4, T5, T6], next xml.Token, err error) {
	var item1 T1
	item1, current, err = readElementDispatched(
		decoder, current, readItem1,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 0},
			)
		}
		return
	}

	var item2 T2
	item2, current, err = readElementDispatched(
		decoder, current, readItem2,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 1},
			)
		}
		return
	}

	var item3 T3
	item3, current, err = readElementDispatched(
		decoder, current, readItem3,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 2},
			)
		}
		return
	}

	var item4 T4
	item4, current, err = readElementDispatched(
		decoder, current, readItem4,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 3},
			)
		}
		return
	}

	var item5 T5
	item5, current, err = readElementDispatched(
		decoder, current, readItem5,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 4},
			)
		}
		return
	}

	var item6 T6
	item6, current, err = readElementDispatched(
		decoder, current, readItem6,
	)
	if err != nil {
		if deseriaErr, ok := err.(*DeserializationError); ok {
			deseriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 5},
			)
		}
		return
	}

	result = aascommon.Tuple6[T1, T2, T3, T4, T5, T6]{
		Item1: item1,
		Item2: item2,
		Item3: item3,
		Item4: item4,
		Item5: item5,
		Item6: item6,
	}
	next = current
	return
}

// Consume the text tokens (char data) as a string-encoded literal of
// [aastypes.Result].
//
// Any comment tokens are skipped.
//
// The resulting `next` token points to the first token which is neither text
// nor comment.
//
// If we reached the end-of-file, `next` is an [eof] sentinel token.
func readTextAs_Result(
	decoder *xml.Decoder,
	current xml.Token,
) (value aastypes.Result,
	next xml.Token,
	err error,
) {
	var text string
	text, next, err = readText(decoder, current)
	if err != nil {
		return
	}

	var ok bool
	value, ok = aasstringification.ResultFromString(text)
	if !ok {
		err = newDeserializationError(
			fmt.Sprintf(
				"Unexpected literal of Result: %v",
				text,
			),
		)
		return
	}

	return
}

// De-serialize an instance of [aastypes.IAbstractItem] based on the `local` name
// of its start element.
//
// The `current` token is expected to point to the content of that start element, and
// the resulting `next` token points to its end element.
func readAbstractItemDispatched(
	decoder *xml.Decoder,
	current xml.Token,
	local string,
) (instance aastypes.IAbstractItem,
	next xml.Token,
	err error,
) {
	switch local {
	case "anotherItem":
		instance, next, err = readAnotherItemAsSequence(decoder, current)
	case "someItem":
		instance, next, err = readSomeItemAsSequence(decoder, current)
	default:
		err = unexpectedDiscriminator(local, "IAbstractItem")
	}
	return
}

// De-serialize the instance of [aastypes.ISomeItem]
// as a sequence of XML elements, each representing a property
// of [aastypes.ISomeItem].
//
// The reading stops as soon as we encounter a non-start element, and we return
// that token as the `next` token.
func readSomeItemAsSequence(
	decoder *xml.Decoder,
	current xml.Token,
) (instance aastypes.ISomeItem,
	next xml.Token,
	err error,
) {
	var theName string

	foundName := false

	for {
		var local string
		var ok bool
		local, current, ok, err = nextProperty(decoder, current, "ISomeItem")
		if err != nil {
			return
		}
		if !ok {
			break
		}

		var valueErr error
		switch local {
		case "name":
			theName, current, valueErr = readText(
				decoder, current,
			)
			foundName = true
		default:
			valueErr = newDeserializationError(
				"Unexpected property",
			)
		}

		current, err = concludeProperty(decoder, current, local, valueErr)
		if err != nil {
			return
		}
	}

	next = current

	if !foundName {
		err = missingProperty("name")
		return
	}

	instance = aastypes.NewSomeItem(
		theName,
	)
	return
}

// De-serialize an instance of [aastypes.ISomeItem] based on the `local` name
// of its start element.
//
// The `current` token is expected to point to the content of that start element, and
// the resulting `next` token points to its end element.
func readSomeItemDispatched(
	decoder *xml.Decoder,
	current xml.Token,
	local string,
) (instance aastypes.ISomeItem,
	next xml.Token,
	err error,
) {
	switch local {
	case "someItem":
		instance, next, err = readSomeItemAsSequence(decoder, current)
	default:
		err = unexpectedStartElement(local, "someItem")
	}
	return
}

// De-serialize the instance of [aastypes.IAnotherItem]
// as a sequence of XML elements, each representing a property
// of [aastypes.IAnotherItem].
//
// The reading stops as soon as we encounter a non-start element, and we return
// that token as the `next` token.
func readAnotherItemAsSequence(
	decoder *xml.Decoder,
	current xml.Token,
) (instance aastypes.IAnotherItem,
	next xml.Token,
	err error,
) {
	var theSerialNumber int64

	foundSerialNumber := false

	for {
		var local string
		var ok bool
		local, current, ok, err = nextProperty(decoder, current, "IAnotherItem")
		if err != nil {
			return
		}
		if !ok {
			break
		}

		var valueErr error
		switch local {
		case "serialNumber":
			theSerialNumber, current, valueErr = readTextAs_long(
				decoder, current,
			)
			foundSerialNumber = true
		default:
			valueErr = newDeserializationError(
				"Unexpected property",
			)
		}

		current, err = concludeProperty(decoder, current, local, valueErr)
		if err != nil {
			return
		}
	}

	next = current

	if !foundSerialNumber {
		err = missingProperty("serialNumber")
		return
	}

	instance = aastypes.NewAnotherItem(
		theSerialNumber,
	)
	return
}

// De-serialize the instance of [aastypes.ISomething]
// as a sequence of XML elements, each representing a property
// of [aastypes.ISomething].
//
// The reading stops as soon as we encounter a non-start element, and we return
// that token as the `next` token.
func readSomethingAsSequence(
	decoder *xml.Decoder,
	current xml.Token,
) (instance aastypes.ISomething,
	next xml.Token,
	err error,
) {
	var thePair aascommon.Tuple2[string, int64]
	var theItems aascommon.Tuple2[aastypes.IAbstractItem, aastypes.IAbstractItem]
	var theTricky aascommon.Tuple6[int64, aastypes.ISomeItem, aastypes.IAbstractItem, aastypes.ISomeItem, int64, aastypes.Result]

	foundPair := false
	foundItems := false
	foundTricky := false

	for {
		var local string
		var ok bool
		local, current, ok, err = nextProperty(decoder, current, "ISomething")
		if err != nil {
			return
		}
		if !ok {
			break
		}

		var valueErr error
		switch local {
		case "pair":
			thePair, current, valueErr = readTuple2(
				decoder, current,
				readAtV1_string,
				readAtV2_long,
			)
			foundPair = true
		case "items":
			theItems, current, valueErr = readTuple2(
				decoder, current,
				readAbstractItemDispatched,
				readAbstractItemDispatched,
			)
			foundItems = true
		case "tricky":
			theTricky, current, valueErr = readTuple6(
				decoder, current,
				readAtV1_long,
				readSomeItemDispatched,
				readAbstractItemDispatched,
				readSomeItemDispatched,
				readAtV5_long,
				readAtV6_Result,
			)
			foundTricky = true
		default:
			valueErr = newDeserializationError(
				"Unexpected property",
			)
		}

		current, err = concludeProperty(decoder, current, local, valueErr)
		if err != nil {
			return
		}
	}

	next = current

	if !foundPair {
		err = missingProperty("pair")
		return
	}

	if !foundItems {
		err = missingProperty("items")
		return
	}

	if !foundTricky {
		err = missingProperty("tricky")
		return
	}

	instance = aastypes.NewSomething(
		thePair,
		theItems,
		theTricky,
	)
	return
}

// De-serialize an instance of [aastypes.IClass] based on the `local` name
// of its start element.
//
// The `current` token is expected to point to the content of that start element, and
// the resulting `next` token points to its end element.
func readClassDispatched(
	decoder *xml.Decoder,
	current xml.Token,
	local string,
) (instance aastypes.IClass,
	next xml.Token,
	err error,
) {
	switch local {
	case "someItem":
		instance, next, err = readSomeItemAsSequence(decoder, current)
	case "anotherItem":
		instance, next, err = readAnotherItemAsSequence(decoder, current)
	case "something":
		instance, next, err = readSomethingAsSequence(decoder, current)
	default:
		err = newDeserializationError(
			fmt.Sprintf(
				"Unexpected XML element name %s as class discriminator",
				local,
			),
		)
	}
	return
}

// Unmarshal an instance of [aastypes.IClass] serialized as an XML element.
//
// The XML element must live in the [Namespace] space.
func Unmarshal(
	decoder *xml.Decoder,
) (instance aastypes.IClass, err error) {
	var current xml.Token
	current, err = readNext(decoder, nil)
	if err != nil {
		return
	}

	instance, _, err = readElementDispatched(
		decoder, current, readClassDispatched,
	)
	return
}

// endregion

// region Serialization

// Represent an error during the serialization.
//
// Implements `error`.
type SerializationError struct {
	Path    *aasreporting.Path
	Message string
}

func newSerializationError(message string) *SerializationError {
	return &SerializationError{
		Path:    &aasreporting.Path{},
		Message: message,
	}
}

func (se *SerializationError) Error() string {
	return fmt.Sprintf(
		"%s: %s",
		se.PathString(),
		se.Message,
	)
}

// Render the path as a string.
func (se *SerializationError) PathString() string {
	return aasreporting.ToGolangPath(se.Path)
}

// Write the start element with the given `local` name to the encoder.
//
// Do not flush.
//
// If the `withNamespace` is set, set the [xml.Name.Space] property in the element
// accordingly.
func writeStartElement(
	encoder *xml.Encoder,
	local string,
	withNamespace bool,
) (err error) {
	startElement := xml.StartElement{Name: xml.Name{Local: local}}
	if withNamespace {
		startElement.Name.Space = Namespace
	}

	err = encoder.EncodeToken(startElement)
	return
}

// Write the end element with the given `local` name to the encoder.
//
// Do not flush.
//
// If the `withNamespace` is set, set the [xml.Name.Space] property in the element
// accordingly.
func writeEndElement(
	encoder *xml.Encoder,
	local string,
	withNamespace bool,
) (err error) {
	endElement := xml.EndElement{Name: xml.Name{Local: local}}
	if withNamespace {
		endElement.Name.Space = Namespace
	}

	err = encoder.EncodeToken(endElement)
	return
}

// Write the `text` to the encoder.
//
// Do not flush.
//
// If `text` is empty, do nothing.
func writeText(
	encoder *xml.Encoder,
	text string,
) (err error) {
	if len(text) > 0 {
		err = encoder.EncodeToken(
			xml.CharData([]byte(text)),
		)
	}
	return
}

// Write the `value` as a `xs:boolean` in a text element.
//
// Do not flush.
func writeAsText_bool(
	encoder *xml.Encoder,
	value bool,
) (err error) {
	text := "true"
	if !value {
		text = "false"
	}
	err = writeText(encoder, text)
	return
}

// Write the `value` as a `xs:long` in a text element.
//
// Do not flush.
func writeAsText_long(
	encoder *xml.Encoder,
	value int64,
) (err error) {
	text := strconv.FormatInt(value, 10)
	err = writeText(encoder, text)
	return
}

// Write the `value` as a `xs:double` in a text element.
//
// Do not flush.
func writeAsText_double(
	encoder *xml.Encoder,
	value float64,
) (err error) {
	var text string

	// See: https://www.w3.org/TR/xmlschema-2/#double
	// for the exact literals.
	if math.IsInf(value, 0) {
		if value < 0 {
			text = "-INF"
		} else {
			text = "INF"
		}
	} else if math.IsNaN(value) {
		text = "NaN"
	} else {
		text = strconv.FormatFloat(value, 'g', -1, 64)
	}

	err = writeText(encoder, text)
	return
}

// Write the `value` as a `xs:string` in a text element.
//
// Do not flush.
func writeAsText_string(
	encoder *xml.Encoder,
	value string,
) (err error) {
	err = writeText(encoder, value)
	return
}

// Write the `value` as a base64-encoded bytes in a text element.
//
// Do not flush.
func writeAsText_bytes(
	encoder *xml.Encoder,
	value []byte,
) (err error) {
	text := b64.StdEncoding.EncodeToString(
		value,
	)

	err = writeText(encoder, text)
	return
}

// Write `that` as an XML element with the `local` name, its content written by
// `writeContent`.
//
// Do not flush.
//
// This is the one place which frames an XML element around a *value*: a property,
// a list item and a tuple item all go through it, and differ only in the given
// `writeContent`. A list frames its own element in [writeList], and an instance
// the element naming its model type in [writeClassElement], as neither of the two
// can be reduced to a content writer without allocating a closure.
//
// The XML namespace is expected to have been defined outside of the resulting XML
// element.
func writeElement[T any](
	encoder *xml.Encoder,
	local string,
	that T,
	writeContent func(anEncoder *xml.Encoder, aValue T) (anErr error),
) (err error) {
	err = writeStartElement(encoder, local, false)
	if err != nil {
		return
	}

	err = writeContent(encoder, that)
	if err != nil {
		return
	}

	err = writeEndElement(encoder, local, false)
	return
}

// Write the optional `that` as an XML element with the `local` name, or write
// nothing at all if it is not set.
//
// Do not flush.
//
// A scalar and a tuple are not nilable in Golang, so an optional one is represented
// as a pointer. The pointer is dereferenced here, so that `writeContent` sees only
// the value. See also [writeOptionalInstance] and [writeOptionalSlice], which differ
// from this function only in how the presence is decided.
func writeOptionalPointer[T any](
	encoder *xml.Encoder,
	local string,
	that *T,
	writeContent func(anEncoder *xml.Encoder, aValue T) (anErr error),
) (err error) {
	if that == nil {
		return
	}

	return writeElement(encoder, local, *that, writeContent)
}

// Write the optional instance `that` as an XML element with the `local` name, or
// write nothing at all if it is not set.
//
// Do not flush.
//
// An instance is represented as an interface and a named union as a pointer to
// a struct, both of which are nil on their own, so -- unlike in [writeOptionalPointer] --
// there is no pointer to dereference.
//
